+  it.effect(
+    "preserves experimental host tools and original dynamic-call coordinates on the wire",
+    () =>
+      Effect.gen(function* () {
+        const { stdio, input, output } = yield* makeInMemoryStdio();
+        const client = yield* CodexClient.make(stdio);
+        const dynamicTools = [
+          {
+            type: "function",
+            name: "read_original_status",
+            description: "Read the original selected command status.",
+            inputSchema: { type: "object", properties: {}, additionalProperties: false },
+          },
+          {
+            type: "namespace",
+            name: "fixture",
+            description: "Fixture status tools.",
+            tools: [
+              {
+                type: "function",
+                name: "read_original_status",
+                description: "Read the original selected command status.",
+                inputSchema: { type: "object", properties: {}, additionalProperties: false },
+                deferLoading: true,
+              },
+            ],
+          },
+        ] as const;
+        const start = yield* client
+          .request("thread/start", { cwd: "/fixture", dynamicTools })
+          .pipe(Effect.exit, Effect.forkScoped);
+        const request = JSON.parse(yield* Queue.take(output));
+        assert.equal(request.method, "thread/start");
+        assert.deepEqual(request.params.dynamicTools, dynamicTools);
+        yield* Queue.offer(
+          input,
+          new TextEncoder().encode(
+            `${JSON.stringify({
+              id: request.id,
+              error: { code: -32000, message: "Fixture does not launch native threads." },
+            })}\n`,
+          ),
+        );
+        assert.equal(Exit.isFailure(yield* Fiber.join(start)), true);
+
+        const original = {
+          threadId: "native-thread:opaque/1",
+          turnId: "native-turn:opaque/1",
+          callId: "native-call:opaque/1",
+          tool: "read_original_status",
+          arguments: {},
+        };
+        const received = yield* Ref.make<Array<unknown>>([]);
+        yield* client.handleServerRequest("item/tool/call", (payload) =>
+          Ref.update(received, (values) => [...values, payload]).pipe(
+            Effect.as({
+              success: false,
+              contentItems: [
+                { type: "inputText" as const, text: "No Control connection enrolled." },
+              ],
+            }),
+          ),
+        );
+        for (const params of [original, { ...original, callId: undefined }]) {
+          yield* Queue.offer(
+            input,
+            new TextEncoder().encode(
+              `${JSON.stringify({ id: "native-request:opaque/1", method: "item/tool/call", params })}\n`,
+            ),
+          );
